package video

import (
	"bytes"
	"encoding/binary"
	"io"
	"os"
	"testing"
	"time"
)

// The fixture is generated by VideoToolbox from synthetic moving pixels, never
// a real user's screen. Each record is uint32BE length followed by FRS1/FRV2.
func TestNativeContinuousAVCCRoundTrip(t *testing.T) {
	path := os.Getenv("FARREACH_NATIVE_FRAME_FIXTURE")
	if path == "" {
		t.Skip("set FARREACH_NATIVE_FRAME_FIXTURE to a continuous native encoder fixture")
	}
	file, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	r := NewRTPReassembler()
	var generation uint64
	var sequence uint64
	packetSequence := uint16(65000)
	keys, deltas := 0, 0
	maxKey, maxDelta := 0, 0
	now := time.Now()
	for {
		var length [4]byte
		if _, err = io.ReadFull(file, length[:]); err == io.EOF {
			break
		} else if err != nil {
			t.Fatal(err)
		}
		n := binary.BigEndian.Uint32(length[:])
		if n < 37 || n > MaxFrame {
			t.Fatal("invalid native fixture bounds")
		}
		original := make([]byte, n)
		if _, err = io.ReadFull(file, original); err != nil {
			t.Fatal(err)
		}
		gen := binary.BigEndian.Uint64(original[4:12])
		if sequence == 0 {
			generation = gen
			r.Reset(gen)
		} else if gen != generation {
			t.Fatal("fixture changed generation")
		}
		sequence++
		if IsKeyframe(original) {
			keys++
			maxKey = max(maxKey, len(original))
		} else {
			deltas++
			maxDelta = max(maxDelta, len(original))
		}
		packets, err := Packetize(original, sequence, uint32(sequence*3000), packetSequence, 1)
		if err != nil {
			t.Fatalf("native frame%d packetization: %v", sequence, err)
		}
		packetSequence += uint16(len(packets))
		if len(packets) < 3 || packets[0].Payload[0]&31 != 7 || packets[1].Payload[0]&31 != 8 {
			t.Fatalf("native frame%d (key=%v) omitted SPS/PPS", sequence, IsKeyframe(original))
		}
		var assembled [][]byte
		for i, packet := range packets {
			frames, lost, err := r.Push(packet, 1, now.Add(time.Duration(sequence)*time.Second/30+time.Duration(i)*time.Microsecond))
			if err != nil || lost {
				t.Fatalf("native frame%d reference loss: %v lost=%v", sequence, err, lost)
			}
			assembled = append(assembled, frames...)
		}
		if len(assembled) != 1 || !bytes.Equal(assembled[0], original) {
			t.Fatalf("native frame%d did not roundtrip byte-for-byte", sequence)
		}
	}
	if sequence < 30 || keys == 0 || deltas < int(sequence)/2 {
		t.Fatalf("fixture must exercise a continuous reference chain: total=%d IDR=%d delta=%d", sequence, keys, deltas)
	}
	t.Logf("NATIVE_RTP_SEQUENCE frames=%d keyframes=%d deltas=%d maxIDRBytes=%d maxDeltaBytes=%d allRoundtripped=true", sequence, keys, deltas, maxKey, maxDelta)
}
